  }, {
    "tStartMs": 2558956,
    "dDurationMs": 2402,
    "segs": [ {
      "utf8": "我都聽的是日本的這個動畫主題歌"
    } ]
  }, {
    "tStartMs": 2561358,
    "dDurationMs": 1635,
    "segs": [ {
      "utf8": "所以後來我都跟朋友 "
    } ]
  }, {
    "tStartMs": 2562993,
    "dDurationMs": 1468,
    "segs": [ {
      "utf8": "在那邊唱日K"
    } ]
  }, {
    "tStartMs": 2564461,
    "dDurationMs": 2803,
    "segs": [ {
      "utf8": "因為我都覺得那個就是某一段時間"
    } ]
  }, {
    "tStartMs": 2567264,
    "dDurationMs": 1452,
    "segs": [ {
      "utf8": "它可以療癒我的東西 "
    } ]
  }, {
    "tStartMs": 2568716,
    "dDurationMs": 750,
    "segs": [ {
      "utf8": "少年的時候"
    } ]
  }, {
    "tStartMs": 2569466,
    "dDurationMs": 1802,
    "segs": [ {
      "utf8": "我們也曾經有過孤單"
    } ]
  }, {
    "tStartMs": 2571268,
    "dDurationMs": 2786,
    "segs": [ {
      "utf8": "都是靠著這些一路這樣撐上來的"
    } ]
  }, {
    "tStartMs": 2574054,
    "dDurationMs": 2203,
    "segs": [ {
      "utf8": "好 我們這次訪談的時間"
    } ]
  }, {
    "tStartMs": 2576257,
    "dDurationMs": 1384,
    "segs": [ {
      "utf8": "是中秋連假"
    } ]
  }, {
    "tStartMs": 2577641,
    "dDurationMs": 2052,
    "segs": [ {
      "utf8": "所以今天我真的是抱著一種"
    } ]
  }, {
    "tStartMs": 2579693,
    "dDurationMs": 2102,
    "segs": [ {
      "utf8": "想把自己內心裡面的感受"
    } ]
  }, {
    "tStartMs": 2581795,
    "dDurationMs": 2303,
    "segs": [ {
      "utf8": "跟Puma老師一起來分享"
    } ]
  }, {
    "tStartMs": 2584098,
    "dDurationMs": 2903,
    "segs": [ {
      "utf8": "然後也希望說我們的頻道的觀眾"
    } ]
  }, {
    "tStartMs": 2587001,
    "dDurationMs": 3186,
    "segs": [ {
      "utf8": "也能夠從裡面去獲得一些溫暖"
    } ]
  }, {
    "tStartMs": 2590187,
    "dDurationMs": 1502,
    "segs": [ {
      "utf8": "跟感受這樣子"
    } ]
  }, {
    "tStartMs": 2591689,
    "dDurationMs": 1268,
    "segs": [ {
      "utf8": "這樣我們就覺得 "
    } ]
  }, {
    "tStartMs": 2592957,
    "dDurationMs": 2435,
    "segs": [ {
      "utf8": "這一集就非常有意義了"
    } ]
  }, {
    "tStartMs": 2595392,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "希望大家會喜歡"
    } ]
  }, {
    "tStartMs": 2596393,
