    "segs": [ {
      "utf8": "希望大家會喜歡"
    } ]
  }, {
    "tStartMs": 2597695,
    "dDurationMs": 3803,
    "segs": [ {
      "utf8": "然後如果還希望工頭找誰來聊天"
    } ]
  }, {
    "tStartMs": 2601498,
    "dDurationMs": 1702,
    "segs": [ {
      "utf8": "大家都可以留言給我"
    } ]
  }, {
    "tStartMs": 2603200,
    "dDurationMs": 4088,
    "segs": [ {
      "utf8": "那我也祝Puma接下來的選舉行程"
    } ]
  }, {
    "tStartMs": 2607288,
    "dDurationMs": 900,
    "segs": [ {
      "utf8": "一切都順利"
    } ]
