    "tStartMs": 2608188,
    "dDurationMs": 801,
    "segs": [ {
      "utf8": "謝謝"
    } ]
  }, {
    "tStartMs": 2608989,
    "dDurationMs": 2202,
    "segs": [ {
      "utf8": "然後大家不要忘記來投稿"
    } ]
  }, {
    "tStartMs": 2611191,
    "dDurationMs": 2103,
    "segs": [ {
      "utf8": "可能播出的時候已經截稿了"
    } ]
  }, {
    "tStartMs": 2613294,
    "dDurationMs": 900,
    "segs": [ {
      "utf8": "但沒關係"
    } ]
  }, {
    "tStartMs": 2614194,
    "dDurationMs": 3204,
    "segs": [ {
      "utf8": "我們一起來聽這個Puma的競選歌曲"
